import importlib.util, itertools, random, sys
spec = importlib.util.spec_from_file_location('m','/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)

def brute(pids, qids, sig, costs, limit=14):
    pairs = [(a,b) for i,a in enumerate(pids) for b in pids[i+1:]
             if any(sig[(q,a)]!=sig[(q,b)] for q in qids)]
    n=len(qids)
    best=None
    for mask in range(1<<n):
        sel=[qids[i] for i in range(n) if mask>>i&1]
        c=sum(costs[q] for q in sel); k=len(sel)
        if best and (c,k)>=best[:2]: continue
        if all(any(sig[(q,a)]!=sig[(q,b)] for q in sel) for a,b in pairs):
            if best is None or (c,k)<best[:2]: best=(c,k,sel)
    return best

RC=['NOERROR','NXDOMAIN','SERVFAIL','REFUSED']
def randsig(rng, np, nq, pids, qids):
    pool=[]
    for i in range(6):
        pool.append((RC[i%4], frozenset({('a%d.'%j,'A','1.0.0.%d'%k) for j,k in
                     zip(range(rng.randint(0,2)), [rng.randint(0,255) for _ in range(3)])})))
    sig={}
    for q in qids:
        base = rng.choice(pool)
        for p in pids:
            sig[(q,p)] = base if rng.random()<0.55 else rng.choice(pool)
    return sig

fails=0
for t in range(4000):
    rng=random.Random(t)
    np_=rng.randint(1,8); nq=rng.randint(0,10)
    pids=['p%d'%i for i in range(np_)]
    qids=['q%d'%i for i in range(nq)]
    costs={q:rng.choice([1,1,2,3,5,9]) for q in qids}
    sig=randsig(rng,np_,nq,pids,qids)
    eq,basis,cost,count = m.select_basis(pids,qids,sig,costs)
    # equivalence check
    groups={}
    for p in pids:
        groups.setdefault(tuple(sig[(q,p)] for q in qids),[]).append(p)
    expeq=sorted(sorted(v) for v in groups.values())
    if eq!=expeq: print('EQ MISMATCH',t); fails+=1; break
    b=brute(pids,qids,sig,costs)
    if b is None:
        b=(0,0,[])
    if (cost,count)!=b[:2] or (sum(costs[x] for x in basis),len(basis))!=(cost,count):
        print('COST MISMATCH',t,(cost,count),b); fails+=1; break
    if basis!=sorted(set(basis)): print('BASIS NOT SORTED',t); fails+=1; break
    if basis!=b[2]:
        # must still be an optimal valid cover
        matrix=sig
        for a,bb in itertools.combinations(pids,2):
            if any(sig[(q,a)]!=sig[(q,bb)] for q in qids):
                if not any(sig[(q,a)]!=sig[(q,bb)] for q in basis):
                    print('BASIS INVALID',t); fails+=1; break
print('small done fails=',fails)

# large: validity + random-subset dominance check
fails2=0
for t in range(60):
    rng=random.Random(10000+t)
    pids=['p%d'%i for i in range(8)]
    qids=['q%d'%i for i in range(20)]
    costs={q:rng.randint(1,20) for q in qids}
    sig={}
    for q in qids:
        for p in pids:
            sig[(q,p)]=(rng.choice(RC), frozenset({('a.','A','1.0.0.%d'%rng.randint(0,3))}))
    eq,basis,cost,count=m.select_basis(pids,qids,sig,costs)
    # validity
    for a,b in itertools.combinations(pids,2):
        if any(sig[(q,a)]!=sig[(q,b)] for q in qids):
            if not any(sig[(q,a)]!=sig[(q,b)] for q in basis):
                print('LARGE INVALID',t); fails2+=1
    # random search for something better
    better=False
    for _ in range(30000):
        k=rng.randint(0,20)
        sel=rng.sample(qids,k)
        c=sum(costs[x] for x in sel)
        if (c,len(sel)) < (cost,count) or (c==cost and len(sel)<count):
            ok=all(any(sig[(q,a)]!=sig[(q,b)] for q in sel) for a,b in itertools.combinations(pids,2)
                   if any(sig[(q,a)]!=sig[(q,b)] for q in qids))
            if ok: better=True; print('BETTER FOUND',t,sel,(c,len(sel)),(cost,count)); fails2+=1; break
    # greedy check
    remaining=list(qids); chosen=[]; 
    pairs=[(a,b) for i,a in enumerate(pids) for b in pids[i+1:] if any(sig[(q,a)]!=sig[(q,b)] for q in qids)]
    uncovered=set(pairs)
    while uncovered:
        bestq=None
        for q in remaining:
            gain=len([p for p in uncovered if sig[(q,p[0])]!=sig[(q,p[1])]])
            if bestq is None or (gain,-costs[q])>(bestg,-costs[bestq]): bestq=q; bestg=gain
        chosen.append(bestq); remaining.remove(bestq)
        uncovered={p for p in uncovered if sig[(bestq,p[0])]==sig[(bestq,p[1])]}
    gc=sum(costs[x] for x in chosen)
    if (gc,len(chosen))<(cost,count): print('GREEDY BETTER',t); fails2+=1
print('large done fails=',fails2)
